public class MyClass {
    //method 1: Adds two integer values
    public int add(int x, int y) {
        return x + y;
    }

    //method 2: Subtracts two integer values
    public int subtract(int x, int y) {
        return x - y;
    }

    //method 3: Calculates average of two integer values
    public double average(int x, int y) {
        return (x + y) / 2.0;
    }
}
